import { Component, createEffect, createMemo, createSignal, For, on, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { isFocusable } from "#core/ui-next/services/focus.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { AdvicePage } from "#base/ui/advice/advice-defines.js";
import { AdvisorPortrait, AdvisorQuoteContainer } from "#base/ui-next/screens/advisor-council/advisor-card.jsx";
import {
	AdvicePanelTypes,
	useAdvisorScreenContext,
} from "#base/ui-next/screens/advisor-council/advisor-screen-model.js";

export interface PortraitTabProps {
	title: string;
	quote: string;
	type: AdvisorType;
}

const PortraitTab: Component<PortraitTabProps> = (props) => {
	const model = useAdvisorScreenContext();
	const isFollowing = () => model.isFollowing(props.type);
	const [isHovered, setIsHovered] = createSignal<boolean>(false);
	const isSmallScreen = useIsSmallScreen();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	return (
		<div class={`advisor-portrait-tab relative ${isSmallScreen() ? "mx-1" : "mx-2"}`}>
			<div
				class={`advice-section-container relative flex flex-col justify-around ${isSmallScreen() ? (isMobile ? "px-2" : "px-4") : "px-0"}`}
			>
				<div class={`${isSmallScreen() && !isMobile ? "mt-8" : "mt-6"}`}>
					<AdvisorPortrait
						title={props.title}
						type={props.type}
						shrink
					/>
				</div>
				<div
					class={`advice-section-title font-title font-black tracking-100 uppercase self-center text-center ${isSmallScreen() ? "text-sm my-5" : "text-base mt-8 mb-13"}`}
					role="columnheader"
				>
					<L10n.Stylize
						class="font-fit-shrink"
						style={{ width: "95%" }}
						text={`LOC_ADVISOR_${props.title}_NAME`}
					/>
				</div>
				<div class={`advice-quote-container flex flex-col ${isSmallScreen() ? "h-80 px-0" : "h-84  px-7"}`}>
					<div class="flex-1">
						<AdvisorQuoteContainer
							isFollowed={!isFollowing()}
							useScrollProxy={isHovered()}
						>
							<L10n.Stylize
								class={`${isMobile ? "my-1 mx-4" : "mt-6 mx-5"} text-accent-3 self-center ${isSmallScreen() ? "text-sm" : "text-base"}`}
								text={props.quote}
							/>
						</AdvisorQuoteContainer>
					</div>
					<VSlot class={`mt-4 ${isMobile && isSmallScreen() ? "mb-3" : "mb-8"} flow-row justify-center`}>
						<AudioContextProvider
							segment="AdvisorScreen"
							vars={{ advisorType: props.title.toLowerCase(), following: (!isFollowing()).toString() }}
						>
							<Button
								class={"w-full"}
								onActivate={() => {
									if (!isFollowing()) model.follow(props.type);
									else model.unfollow(props.type);
								}}
								hotkeyAction="shell-action-2"
								navTrayText={isFollowing() ? "LOC_UI_ADVISORS_UNFOLLOW" : "LOC_UI_ADVISORS_FOLLOW"}
								disableFocus
							>
								<div
									class={`w-full flex items-center justify-center pointer-events-none`}
									style={{ width: "90%" }}
								>
									<Icon
										class="size-8 bg-no-repeat bg-contain bg-center mx-1 pointer-events-none"
										name={
											isFollowing()
												? "url(blp:advScreen_button_following_highres)"
												: "url(blp:advScreen_button_notFollowing_highres)"
										}
									/>
									<Show
										when={isFollowing()}
										fallback={
											<L10n.Stylize
												text={"LOC_ADVISOR_COUNCIL_FOLLOW"}
												class={`font-fit-shrink pointer-events-none ${isSmallScreen() ? "text-2xs" : "text-base"}`}
											/>
										}
									>
										<L10n.Stylize
											text={"LOC_ADVISOR_COUNCIL_UNFOLLOW"}
											class={`font-fit-shrink pointer-events-none ${isSmallScreen() ? "text-2xs" : "text-base"}`}
										/>
									</Show>
								</div>
							</Button>
						</AudioContextProvider>
					</VSlot>
				</div>
			</div>
			<Show when={IsControllerActive()}>
				<div
					class={"advice-section-focusable absolute"}
					use:isFocusable={[true, undefined]}
					tabIndex={-1}
					onFocusIn={() => {
						setIsHovered(true);
						model.setSelectedPanel(AdvicePanelTypes.None);
					}}
					onFocusOut={() => {
						setIsHovered(false);
					}}
				/>
			</Show>
		</div>
	);
};

export interface MessageTabProps {
	messageTitle: string;
	messageDescription: string;
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const MessageTab: Component<MessageTabProps> = (props) => {
	const [isHovered, setIsHovered] = createSignal<boolean>(false);

	const model = useAdvisorScreenContext();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	return (
		<div
			class={`relative self-center over overflow-y-hidden ${!isSmallScreen() || !IsControllerActive() ? "advisor-message-tab" : "advisor-message-tab-compact"}  ${isSmallScreen() ? "mx-1" : "mx-2"}`}
			ref={props.ref}
		>
			<div class="advice-section-container relative text-accent-2">
				<ScrollArea
					class={`flex-auto h-full ${isMobile ? "py-3" : "py-1"}`}
					useProxy={isHovered()}
					allowGamepadPan={isHovered()}
				>
					<div class={`advice-section-scroll-area ${isSmallScreen() ? "px-6" : "px-10"}`}>
						<div
							class={"mb-5 ml-2 text-center"}
							role="columnheader"
						>
							<div class="advisor-card-title font-title-lg font-black tracking-100 uppercase">
								<L10n.Stylize text={props.messageTitle} />
							</div>
							<Filigree.Small class="self-center" />
						</div>
						<div role="textbox">
							<Show
								when={IsControllerActive() && model.getSelectedPanel() !== AdvicePanelTypes.Message}
								fallback={
									<L10n.Stylize
										class="text-accent-3 text-base"
										text={props.messageDescription}
									/>
								}
							>
								<L10n.Stylize
									class="text-accent-3 text-base"
									text={props.messageDescription}
									disableTooltips
								/>
							</Show>
						</div>
					</div>
				</ScrollArea>
			</div>
			<Show when={IsControllerActive()}>
				<Activatable
					class={`advice-section-focusable ${model.getSelectedPanel() == AdvicePanelTypes.Message ? "inspect-highlight " : ""}grow shrink overflow-hidden self-center pointer-events-none absolute`}
					onFocusIn={() => {
						setIsHovered(true);
						model.setSelectedPanel(AdvicePanelTypes.Quote);
					}}
					onFocusOut={() => {
						setIsHovered(false);
					}}
					onActivate={() => {
						model.setSelectedPanel(AdvicePanelTypes.Message);
					}}
				/>
			</Show>
		</div>
	);
};

export interface NoteTabProps {
	noteTitle: string;
	noteDescription: string;
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const NoteTab: Component<NoteTabProps> = (props) => {
	const [isHovered, setIsHovered] = createSignal<boolean>(false);

	const model = useAdvisorScreenContext();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	return (
		<div
			class={`relative overflow-y-hidden ${!isSmallScreen() || !IsControllerActive() ? "advisor-note-tab" : "advisor-note-tab-compact"} ${isSmallScreen() ? "mx-1" : "mx-2"}`}
			ref={props.ref}
		>
			<div class="advice-section-container relative ">
				<ScrollArea
					class={`flex-auto h-full ${isMobile ? "py-3" : "py-1"}`}
					useProxy={isHovered()}
					allowGamepadPan={isHovered()}
				>
					<div class={`advice-section-scroll-area pt-1 ${isSmallScreen() ? "px-6" : "px-10"}`}>
						<div class={"mb-6  text-center"}>
							<div
								class={"font-title font-black tracking-100 uppercase text-center my-0 text-accent-2"}
								role="columnheader"
							>
								<L10n.Stylize text={props.noteTitle} />
							</div>
							<div class="w-full filigree-divider-inner-frame white-filigree-divider my-4" />
						</div>

						<div role="textbox">
							<Show
								when={IsControllerActive() && model.getSelectedPanel() !== AdvicePanelTypes.Note}
								fallback={
									<L10n.Stylize
										class="text-accent-3 text-base"
										text={props.noteDescription}
									/>
								}
							>
								<L10n.Stylize
									class="text-accent-3 text-base"
									text={props.noteDescription}
									disableTooltips
								/>
							</Show>
						</div>
					</div>
				</ScrollArea>
			</div>
			<Show when={IsControllerActive()}>
				<Activatable
					class={`advice-section-focusable ${model.getSelectedPanel() == AdvicePanelTypes.Note ? "inspect-highlight " : ""}pointer-events-none absolute`}
					onFocusIn={() => {
						setIsHovered(true);
						model.setSelectedPanel(AdvicePanelTypes.None);
					}}
					onFocusOut={() => {
						setIsHovered(false);
					}}
					onActivate={() => {
						model.setSelectedPanel(AdvicePanelTypes.Note);
					}}
					disableFocus={model.getSelectedPanel() === AdvicePanelTypes.Message}
				/>
			</Show>
		</div>
	);
};

export interface AdvisorTabProps {
	type: AdvisorType;
	title: string;
	pages: AdvicePage[];
	defaultTab?: string | undefined;
}

export const AdvisorTab: Component<AdvisorTabProps> = (props) => {
	// If HTML attribute for page-id has been set: navigate there. Otherwise go to the last page.
	const defaultAdviceTabId = createMemo(() => {
		return props.defaultTab && props.pages.find((page) => page.id === props.defaultTab)
			? props.defaultTab
			: props.pages[props.pages.length - 1].id;
	});
	const isFollowing = () => model.isFollowing(props.type);
	const model = useAdvisorScreenContext();
	const isSmallScreen = useIsSmallScreen();
	const isMobileSmallScreen = ViewExperience() == UIViewExperience.Mobile && isSmallScreen();

	let messageTabRef!: HTMLDivElement;
	let noteTabRef!: HTMLDivElement;

	createEffect(
		on([IsControllerActive, model.getSelectedPanel], () => {
			waitForLayout(() => {
				// Focus on the first tooltip when a panel has been inspected with controller
				if (IsControllerActive()) {
					let firstTooltip: HTMLElement | null = null;
					if (model.getSelectedPanel() === AdvicePanelTypes.Message) {
						firstTooltip = messageTabRef.querySelector(".tooltip-keyword");
					}
					if (model.getSelectedPanel() === AdvicePanelTypes.Note) {
						firstTooltip = noteTabRef.querySelector(".tooltip-keyword");
					}
					if (firstTooltip instanceof HTMLElement) {
						FocusManager.get().setFocus(firstTooltip);
					}
				}
			});
		}),
	);

	return (
		<div class="size-full">
			<Tab
				class="w-full flex flex-col flex-auto pointer-events-auto relative"
				defaultTab={defaultAdviceTabId()}
			>
				<For each={props.pages}>
					{(page, index) => {
						return (
							<Tab.Item
								name={page.id}
								title={() => <L10n.Compose text={`${props.title}-advice${index()}`} />}
								body={() => (
									<HSlot
										class={`advisor-tabs-container flex justify-center w-full ${isMobileSmallScreen && IsControllerActive() ? "pb-6" : ""}`}
									>
										<Show when={model.getSelectedPanel()}>
											{(!isSmallScreen() || !IsControllerActive()) && (
												<PortraitTab
													title={props.title}
													quote={page.quote}
													type={props.type}
												/>
											)}

											<MessageTab
												messageTitle={page.title}
												messageDescription={page.message}
												ref={messageTabRef}
											/>

											<NoteTab
												noteTitle={page.noteTitle}
												noteDescription={page.noteDescription}
												ref={noteTabRef}
											/>
										</Show>
									</HSlot>
								)}
							/>
						);
					}}
				</For>
				<Tab.Output />
				<HSlot
					class={`w-full h-1\\/8 flow-col ${isSmallScreen() ? "my-2" : "my-5"} ${IsControllerActive() && isSmallScreen() ? "justify-end" : "justify-center"}`}
				>
					<div class="mx-10">
						<Tab.TabListPips
							showPages
							nextHotkey="nav-shell-next"
							previousHotkey="nav-shell-previous"
						/>
					</div>
				</HSlot>
			</Tab>
			{/* Stand-in navTray text for focusing panel tooltips */}
			<Show
				when={
					model.getSelectedPanel() !== AdvicePanelTypes.Message &&
					model.getSelectedPanel() !== AdvicePanelTypes.Note
				}
			>
				<Activatable
					hotkeyAction={"accept"}
					navTrayText={"LOC_UI_ADVISORS_INSPECT"}
					disableFocus
				/>
			</Show>
			{/* Back out of tooltip focus */}
			<Show
				when={
					model.getSelectedPanel() === AdvicePanelTypes.Message ||
					model.getSelectedPanel() === AdvicePanelTypes.Note
				}
			>
				<Activatable
					hotkeyAction={"cancel"}
					onActivate={() => {
						if (model) model.setSelectedPanel(AdvicePanelTypes.None);
					}}
					disableFocus
				/>
			</Show>
			<Show when={IsControllerActive() && isSmallScreen()}>
				<Button
					class={"w-full h-10"}
					onActivate={() => {
						if (IsControllerActive()) {
							model.playFollowAudio(props.type);
						}
						if (!isFollowing()) model.follow(props.type);
						else model.unfollow(props.type);
					}}
					hotkeyAction="shell-action-2"
					navTrayText={isFollowing() ? "LOC_UI_ADVISORS_UNFOLLOW" : "LOC_UI_ADVISORS_FOLLOW"}
					disableFocus
				/>
			</Show>
		</div>
	);
};
